// Benchmark boilerplate generated by Benchmark

import Benchmark
import Foundation
import SolidPDF
import SolidPDFParsingBenchmarkSupport

let benchmarks: @Sendable () -> Void = {
  let configuration = Benchmark.Configuration(
    metrics: [.wallClock, .cpuTotal, .mallocCountTotal, .peakMemoryResidentDelta],
    warmupIterations: 3,
    scalingFactor: .one,
    maxDuration: .seconds(10),
    maxIterations: 100
  )
  let small = try! PDFParsingBenchmarkFixtures.document(version: .v1_7)
  let classic = try! PDFParsingBenchmarkFixtures.document(
    version: .v1_7,
    additionalObjectCount: 10_000
  )
  let stream = try! PDFParsingBenchmarkFixtures.document(
    version: .v2_0,
    additionalObjectCount: 10_000
  )
  let objectStream = PDFParsingBenchmarkFixtures.objectStreamDocument(containedObjectCount: 1_000)
  let coldFile = FileManager.default.temporaryDirectory
    .appendingPathComponent("SolidPDFParsingBenchmark-(UUID().uuidString).pdf")
  try! classic.write(to: coldFile)

  registerOpen("Header and Tail Scan", data: small, configuration: configuration)
  registerOpen("10,000-Object Classic XRef", data: classic, configuration: configuration)
  registerOpen("10,000-Object XRef Stream", data: stream, configuration: configuration)

  Benchmark("Repeated Lazy Root Lookup", configuration: configuration) { benchmark in
    let document = try await PDFDocument(source: PDFDataInputSource(classic))
    _ = try await document.resolve(document.root)
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      blackHole(try await document.resolve(document.root))
    }
    benchmark.stopMeasurement()
    await document.close()
  }

  Benchmark("Object Stream Lookup", configuration: configuration) { benchmark in
    let document = try await PDFDocument(source: PDFDataInputSource(objectStream))
    let reference = try PDFObjectReference(objectNumber: 1_003, generationNumber: 0)
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      blackHole(try await document.resolve(reference))
    }
    benchmark.stopMeasurement()
    await document.close()
  }

  Benchmark("Cold File Open", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let document = try await PDFDocument(source: PDFFileInputSource(url: coldFile))
      blackHole(try await document.resolve(document.root))
      await document.close()
    }
  }
}

private func registerOpen(
  _ name: String,
  data: Data,
  configuration: Benchmark.Configuration
) {
  Benchmark(name, configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let document = try await PDFDocument(source: PDFDataInputSource(data))
      blackHole(document.root)
      await document.close()
    }
  }
}
